def tr_lower(s):
    mapping = {
        'İ': 'i', 'I': 'ı', 'Ş': 'ş', 'Ğ': 'ğ', 'Ü': 'ü', 'Ö': 'ö', 'Ç': 'ç'
    }
    # Önce büyük harf dönüşümü (Türkçe kuralları ile)
    res = ""
    for char in s:
        if char == 'İ': res += 'i'
        elif char == 'I': res += 'ı'
        else: res += char.lower()
    return res

def tr_upper(s):
    mapping = {
        'i': 'İ', 'ı': 'I', 'ş': 'Ş', 'ğ': 'Ğ', 'ü': 'Ü', 'ö': 'Ö', 'ç': 'Ç'
    }
    res = ""
    for char in s:
        if char == 'i': res += 'İ'
        elif char == 'ı': res += 'I'
        else: res += char.upper()
    return res

def tr_sorted(words):
    # Türkçe karakter sırası (küçük harf bazlı)
    tr_order = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
    # Karakterlerin indexlerini içeren bir sözlük
    order_map = {char: i + 100 for i, char in enumerate(tr_order)} # Harfler sona gelsin diye offset veriyoruz

    def get_sort_key(word):
        # Kelimeyi Türkçe kurallarıyla küçültüyoruz (büyük/küçük harf duyarsız sıralama için)
        lowered = tr_lower(word)
        key = []
        for char in lowered:
            if char in order_map:
                key.append(order_map[char])
            else:
                # Listede olmayanlar (boşluk, nokta vb.) en başta ve Unicode sırasına göre
                key.append(ord(char))
        return key

    # Python'un sort() metodu zaten "stable"dır (eşit olanların sırasını korur)
    return sorted(words, key=get_sort_key)

# Test senaryoları
test_cases = [
    {
        "input": ["İstanbul", "istanbul", "İSTANBUL"],
        "expected_lower": ["istanbul", "istanbul", "istanbul"] # tr_lower kontrolü için değil, sıralama mantığı için
    },
    {
        "input": ["Çay", "çay", "A", "a", "ı", "I", "İ", "i"],
        "expected": ["A", "a", "çay", "Çay", "ı", "I", "İ", "i"] # Bu test karmaşık olabilir, manuel kontrol edeceğiz
    }
]

# Basit bir doğrulama testi
def test_logic():
    # tr_lower test
    assert tr_lower("İSTANBUL") == "istanbul"
    assert tr_lower("IĞDIR") == "ıgdır"

    # tr_upper test
    assert tr_upper("istanbul") == "İSTANBUL"
    assert tr_upper("ışık") == "IŞIK"

    # tr_sorted test (Özel sıralama)
    words = ["ç", "a", "b", "z", "ş", "ı", "i", "ö", "ü", "ğ"]
    # Beklenen: a, b, ç, g(yok), ğ, h(yok), ı, i, j... ş, u, ü, v, w, x, y, z
    # Senin sıralaman: abcçdefgğhıijklmnoöpqrsştuüvwxyz
    # Karakter sırası kontrolü: a=0, b=1, c=2, ç=3...
    sorted_words = tr_sorted(words)
    print("Sorted words:", sorted_words)

test_logic()

def tr_lower(s):
    res = []
    for char in s:
        if char == 'İ':
            res.append('i')
        elif char == 'I':
            res.append('ı')
        else:
            res.append(char.lower())
    return "".join(res)

def tr_upper(s):
    res = []
    for char in s:
        if char == 'i':
            res.append('İ')
        elif char == 'ı':
            res.append('I')
        else:
            res.append(char.upper())
    return "".join(res)

def tr_sorted(words):
    tr_order = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
    order_map = {char: i for i, char in enumerate(tr_order)}

    def get_sort_key(word):
        lowered = tr_lower(word)
        key = []
        for char in lowered:
            if char in order_map:
                # Listede olanlar (1 ile başla ki 0'dan büyük olsun, yani sonda kalsın)
                key.append((1, order_map[char]))
            else:
                # Listede olmayanlar (0 ile başla, en başta yer alsın)
                key.append((0, ord(char)))
        return key

    return sorted(words, key=get_sort_key)

def test_all():
    # tr_lower tests
    assert tr_lower("İSTANBUL") == "istanbul"
    assert tr_lower("IĞDIR") == "ıgdır"
    assert tr_lower("ABCçĞıİ") == "abcçğıi"

    # tr_upper tests
    assert tr_upper("istanbul") == "İSTANBUL"
    assert tr_upper("ışık") == "IŞIK"
    assert tr_upper("abcçğıi") == "ABCÇĞIİ"

    # tr_sorted tests
    # Karakter sırası: abcçdefgğhıijklmnoöpqrsştuüvwxyz
    test_words = ["z", "a", "ç", "b", "ş", "ı", "i", "ö", "ü", "ğ", " ", "!"]
    # Beklenen sıralama (küçük harf duyarsız): 
    # ' ' ve '!' en başta: ord(' ') = 32, ord('!') = 33.
    # Sonra alfabetik: a, b, ç, d(yok), e(yok), f(yok), g(yok), ğ, h(yok), ı, i, ..., ş, u(yok), ü, v(yok), w(yok), x(yok), y(yok), z
    # Not: 'd', 'e', 'f', 'g' gibi harfler listede var ama test listesinde yok. 
    # Eğer listede varsa (0-25 arası index) sıralamaya dahil edilirler.

    sorted_res = tr_sorted(test_words)
    print("Sorted:", sorted_res)

    assert sorted_res[0] == " "
    assert sorted_res[1] == "!"
    # 'a' ve 'A' aynı key'e sahip olacak. Girdi sırasını korumalıdır (stable sort).
    words2 = ["ç", "a", "b", "z", "ş", "ı", "i", "ö", "ü", "ğ"]
    # Beklenen: a, b, ç, ğ, ı, i, ö, ş, ü, z
    expected_order = ["a", "b", "ç", "ğ", "ı", "i", "ö", "ş", "ü", "z"]
    res2 = tr_sorted(words2)
    assert res2 == expected_order
    print("All tests passed!")

test_all()

